# Generated by manage.py generate_test_cases.
from collections.abc import Callable
from unittest.mock import patch

from bs4 import BeautifulSoup
from django.http import HttpResponse
from django.utils.translation import gettext_lazy

from bloomerp.models.project_management.todo_label import TodoLabel
from bloomerp.models.workspaces.workspace import Workspace
from bloomerp.tests.base import (
    BloomerpModelViewTestCase,
    ExpectedResult,
    ModelRequestScenario,
    RequestScenario,
)


class TestBloomerpListView(BloomerpModelViewTestCase):
    """Verify plural page labels without changing list routes or permissions."""

    view_name = "model"
    auto_create_customers = False

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover rendered list labels for navigation, plural forms and access."""
        return [
            ModelRequestScenario(
                name="Full page shows the model plural",
                model=self.CustomerModel,
                user=self.admin_user,
                expected=ExpectedResult(response_validators=self.has_title("customers")),
            ),
            ModelRequestScenario(
                name="HTMX navigation shows the model plural",
                model=self.CustomerModel,
                user=self.admin_user,
                headers={"HX-Request": "true", "HX-Target": "main-content"},
                expected=ExpectedResult(response_validators=self.has_title("customers")),
            ),
            ModelRequestScenario(
                name="History restoration shows the model plural",
                model=self.CustomerModel,
                user=self.admin_user,
                headers={"HX-Request": "true", "HX-History-Restore-Request": "true"},
                expected=ExpectedResult(response_validators=self.has_title("customers")),
            ),
            ModelRequestScenario(
                name="Custom lazy plural is used without adding a suffix",
                model=self.CustomerModel,
                user=self.admin_user,
                prepare=self.use_custom_plural,
                cleanup=self.restore_plural,
                expected=ExpectedResult(response_validators=self.has_title("People")),
            ),
            ModelRequestScenario(
                name="Multiword plural keeps existing capitalization conventions",
                model=TodoLabel,
                user=self.admin_user,
                expected=ExpectedResult(response_validators=self.has_title("Todo Labels")),
            ),
            ModelRequestScenario(
                name="Lazy plural is translated in the request language",
                model=Workspace,
                user=self.admin_user,
                headers={"Accept-Language": "nl"},
                expected=ExpectedResult(response_validators=self.has_title("Werkruimten")),
            ),
            ModelRequestScenario(
                name="List view still requires global view permission",
                model=self.CustomerModel,
                user=self.normal_user,
                expected=ExpectedResult(status_code=403),
            ),
            ModelRequestScenario(
                name="Anonymous list requests still require login",
                model=self.CustomerModel,
                expected=ExpectedResult(status_code=302),
            ),
        ]

    def has_title(self, title: str) -> Callable[[HttpResponse], bool]:
        """Check the rendered breadcrumb uses the route label and original URL."""
        def validate(response: HttpResponse) -> bool:
            """Validate the visible active label and this request's list context."""
            context = response.context
            route = self.get_route(model=context["model"])
            active = BeautifulSoup(response.content, "html.parser").select_one(
                'nav[aria-label="Breadcrumb"] a[aria-current="page"]'
            )
            return (
                route.name_message == "{model_plural}"
                and route.localized_name == title
                and context["route_title"] == title
                and active is not None
                and active.get_text(strip=True) == title.title()
                and active.get("hx-get") == response.wsgi_request.path
            )

        return validate

    def use_custom_plural(self, scenario: RequestScenario) -> None:
        """Temporarily supply an irregular, lazily evaluated model plural."""
        self.plural_patch = patch.object(
            self.CustomerModel._meta, "verbose_name_plural", gettext_lazy("People")
        )
        self.plural_patch.start()

    def restore_plural(self, scenario: RequestScenario) -> None:
        """Restore model metadata after the irregular-plural request."""
        self.plural_patch.stop()
